%% resolveFrom — laws/decomposition.lawspec:184
resolve_from(Schema, Symbols, Entries, Done, Fuel) ->
    lawspec_beam_runtime:contextual(
        <<"cake.laws.decomposition::resolveFrom">>,
        fun() ->
            case (Fuel =:= 0) of
                true ->
                    Done;
                false ->
                    lawspec_beam_runtime:bind(
                        lawspec_definitions:first_ready(
                            Schema,
                            Symbols,
                            Entries,
                            Done,
                            lawspec_beam_runtime:helper(
                                <<"range">>,
                                [
                                    0,
                                    lawspec_beam_runtime:helper(
                                        <<"length">>,
                                        [Entries],
                                        [<<"List cake.laws.decomposition::type::Entry">>],
                                        64
                                    )
                                ],
                                [<<"Integer">>, <<"Integer">>],
                                64
                            )
                        ),
                        fun(It) ->
                            lawspec_beam_schema:match(
                                It,
                                #{
                                    <<"Maybe::Present">> => fun([Selection]) ->
                                        lawspec_definitions:resolve_from(
                                            Schema,
                                            Symbols,
                                            Entries,
                                            lawspec_beam_runtime:helper(
                                                <<"append">>,
                                                [
                                                    Done,
                                                    lawspec_beam_schema:construct(
                                                        <<"List::Cons">>,
                                                        [Selection, []],
                                                        {<<"List">>, [{<<"Integer">>, []}]},
                                                        Schema
                                                    )
                                                ],
                                                [<<"List Integer">>, <<"List Integer">>],
                                                64
                                            ),
                                            lawspec_beam_schema:validate(
                                                lawspec_beam_scalar:convert(
                                                    (Fuel - 1),
                                                    {<<"BigUInt">>, []},
                                                    64
                                                ),
                                                {<<"BigUInt">>, []},
                                                Schema
                                            )
                                        )
                                    end,
                                    <<"Maybe::Absent">> => fun([]) -> Done end
                                }
                            )
                        end
                    )
            end
        end
    ).

%% ringFrom — laws/decomposition.lawspec:101
ring_from(Schema, Symbols, Size, I, Remaining) ->
    lawspec_beam_runtime:contextual(
        <<"cake.laws.decomposition::ringFrom">>,
        fun() ->
            case (Remaining =:= 0) of
                true ->
                    [];
                false ->
                    case (Size >= 1) of
                        true ->
                            lawspec_beam_schema:construct(
                                <<"List::Cons">>,
                                [
                                    lawspec_beam_runtime:bind(
                                        lawspec_beam_runtime:helper(
                                            <<"append">>,
                                            [
                                                <<"sub-question ">>,
                                                lawspec_beam_runtime:helper(
                                                    <<"textOf">>,
                                                    [I],
                                                    [<<"BigUInt">>],
                                                    64
                                                )
                                            ],
                                            [<<"Text">>, <<"Text">>],
                                            64
                                        ),
                                        fun(RecordField) ->
                                            lawspec_beam_runtime:bind(
                                                lawspec_beam_schema:construct(
                                                    <<"List::Cons">>,
                                                    [
                                                        lawspec_beam_scalar:remainder(
                                                            (I + 1),
                                                            Size,
                                                            <<"Integer">>,
                                                            <<"Integer">>
                                                        ),
                                                        []
                                                    ],
                                                    {<<"List">>, [{<<"Integer">>, []}]},
                                                    Schema
                                                ),
                                                fun(RecordField_2) ->
                                                    lawspec_beam_schema:construct(
                                                        <<"cake.laws.decomposition::type::Entry::Entry">>,
                                                        [RecordField, RecordField_2],
                                                        {
                                                            <<"cake.laws.decomposition::type::Entry">>,
                                                            []
                                                        },
                                                        Schema
                                                    )
                                                end
                                            )
                                        end
                                    ),
                                    lawspec_definitions:ring_from(
                                        Schema,
                                        Symbols,
                                        Size,
                                        lawspec_beam_schema:validate(
                                            lawspec_beam_scalar:convert(
                                                (I + 1),
                                                {<<"BigUInt">>, []},
                                                64
                                            ),
                                            {<<"BigUInt">>, []},
                                            Schema
                                        ),
                                        lawspec_beam_schema:validate(
                                            lawspec_beam_scalar:convert(
                                                (Remaining - 1),
                                                {<<"BigUInt">>, []},
                                                64
                                            ),
                                            {<<"BigUInt">>, []},
                                            Schema
                                        )
                                    )
                                ],
                                {<<"List">>, [{<<"cake.laws.decomposition::type::Entry">>, []}]},
                                Schema
                            );
                        false ->
                            []
                    end
            end
        end
    ).

